  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Determine whether this trip's time interval conflicts with another proposed time interval.
   * Algorithm:
   * 1. If newDepartureTime or newArrivalTime is null, return false.
   * 2. If this trip's departureTime or arrivalTime is null, return false.
   * 3. Parse this trip's departureTime and arrivalTime and the provided times into comparable time values.
   * 4. If the proposed interval is invalid, return false.
   * 5. Determine overlap using strict interval intersection:
   *    - Conflict exists when the two intervals share any positive-length time intersection.
   *    - If one interval ends exactly when the other starts, return false.
   * 6. Return true if the intervals overlap; otherwise return false.
   * Related Features:
   * - departureTime
   * - arrivalTime
   * Related Classes: None
   * Input:
   * - newDepartureTime: proposed departure time as a string.
   * - newArrivalTime: proposed arrival time as a string.
   * Output:
   * - boolean
   * - true if the current trip conflicts with the proposed interval; otherwise false.
   * Pre-condition:
   * - Current trip has departureTime and arrivalTime values that can be compared.
   * - Input times are in the same time format as stored values.
   * Post-condition:
   * - No state is changed.
   * - Boundary-adjacent intervals are treated as non-conflicting.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isTimeConflicting(final String newDepartureTime, final String newArrivalTime)
  {
    if (newDepartureTime == null || newArrivalTime == null || departureTime == null || arrivalTime == null)
    {
      return false;
    }
    try
    {
      String[] currentDepParts = departureTime.split(":");
      String[] currentArrParts = arrivalTime.split(":");
      String[] newDepParts = newDepartureTime.split(":");
      String[] newArrParts = newArrivalTime.split(":");
      if (currentDepParts.length < 2 || currentArrParts.length < 2 || newDepParts.length < 2 || newArrParts.length < 2)
      {
        return false;
      }

      int currentDep = Integer.parseInt(currentDepParts[0].trim()) * 60 + Integer.parseInt(currentDepParts[1].trim());
      int currentArr = Integer.parseInt(currentArrParts[0].trim()) * 60 + Integer.parseInt(currentArrParts[1].trim());
      int proposedDep = Integer.parseInt(newDepParts[0].trim()) * 60 + Integer.parseInt(newDepParts[1].trim());
      int proposedArr = Integer.parseInt(newArrParts[0].trim()) * 60 + Integer.parseInt(newArrParts[1].trim());

      if (currentDep >= currentArr || proposedDep >= proposedArr)
      {
        return false;
      }

      return currentDep < proposedArr && proposedDep < currentArr;
    }
    catch (Exception e)
    {
      return false;
    }
  }

